// Generated by vibelang from src/sequence/options.ts; the migrate flow writes it again with each batch.
export const DEFAULT_MIN_PARTICIPANT_GAP = 18;
export const DEFAULT_FRAGMENT_BORDER_STYLE = "rounded";
export function normalizeSequenceMinParticipantGap(value) {
    return value === undefined || !Number.isFinite(value) ? DEFAULT_MIN_PARTICIPANT_GAP : Math.max(1, Math.floor(value));
}
